// Standalone Android/Linux EGL smoke test; does not modify Beat Saber.
// Loads the translated pipelines generated by make_probe.py. Exit 0 means
// both non-layered eye renders produced the expected pixels on THIS driver.
#include <EGL/egl.h>
#include <GLES3/gl32.h>
#include <array>
#include <cstdio>
#include <fstream>
#include <iterator>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>

static void Require(bool ok, std::string const& message) {
  if (!ok) throw std::runtime_error(message);
}

struct Context {
  EGLDisplay display = EGL_NO_DISPLAY;
  EGLContext context = EGL_NO_CONTEXT;
  EGLSurface surface = EGL_NO_SURFACE;
  ~Context() {
    if (display == EGL_NO_DISPLAY) return;
    eglMakeCurrent(display, EGL_NO_SURFACE, EGL_NO_SURFACE, EGL_NO_CONTEXT);
    if (surface != EGL_NO_SURFACE) eglDestroySurface(display, surface);
    if (context != EGL_NO_CONTEXT) eglDestroyContext(display, context);
    eglTerminate(display);
  }
  void Init() {
    display = eglGetDisplay(EGL_DEFAULT_DISPLAY);
    Require(display != EGL_NO_DISPLAY && eglInitialize(display, nullptr, nullptr), "eglInitialize failed");
    Require(eglBindAPI(EGL_OPENGL_ES_API), "eglBindAPI failed");
    EGLint const attributes[] = {EGL_SURFACE_TYPE, EGL_PBUFFER_BIT, EGL_RENDERABLE_TYPE, EGL_OPENGL_ES3_BIT,
                                 EGL_RED_SIZE, 8, EGL_GREEN_SIZE, 8, EGL_BLUE_SIZE, 8, EGL_ALPHA_SIZE, 8, EGL_NONE};
    EGLConfig config{};
    EGLint count = 0;
    Require(eglChooseConfig(display, attributes, &config, 1, &count) && count == 1, "no ES3 pbuffer config");
    EGLint const ctx[] = {EGL_CONTEXT_CLIENT_VERSION, 3, EGL_NONE};
    context = eglCreateContext(display, config, EGL_NO_CONTEXT, ctx);
    Require(context != EGL_NO_CONTEXT, "eglCreateContext failed");
    EGLint const size[] = {EGL_WIDTH, 32, EGL_HEIGHT, 32, EGL_NONE};
    surface = eglCreatePbufferSurface(display, config, size);
    Require(surface != EGL_NO_SURFACE && eglMakeCurrent(display, surface, surface, context), "eglMakeCurrent failed");
  }
};

static GLuint Compile(GLenum stage, std::string const& path) {
  std::ifstream file(path, std::ios::binary);
  Require(file.good(), "cannot read " + path);
  std::string const text((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
  char const* source = text.c_str();
  GLuint shader = glCreateShader(stage);
  glShaderSource(shader, 1, &source, nullptr);
  glCompileShader(shader);
  GLint ok = 0;
  glGetShaderiv(shader, GL_COMPILE_STATUS, &ok);
  if (!ok) {
    std::array<char, 8192> log{};
    glGetShaderInfoLog(shader, static_cast<GLsizei>(log.size()), nullptr, log.data());
    glDeleteShader(shader);
    throw std::runtime_error(path + ": " + log.data());
  }
  return shader;
}

static void DrawEye(std::string const& directory, std::string const& eye, int expected, bool depth = false) {
  std::string const prefix = directory + "/" + eye;
  GLuint program = glCreateProgram();
  for (auto const& [stage, suffix] : std::array<std::pair<GLenum, char const*>, 3>{
         {{GL_VERTEX_SHADER, ".vert"}, {GL_GEOMETRY_SHADER, ".geom"}, {GL_FRAGMENT_SHADER, ".frag"}}}) {
    GLuint shader = Compile(stage, prefix + (depth && stage == GL_FRAGMENT_SHADER ? ".depth.frag" : suffix));
    glAttachShader(program, shader);
    glDeleteShader(shader);
  }
  glLinkProgram(program);
  GLint linked = 0;
  glGetProgramiv(program, GL_LINK_STATUS, &linked);
  if (!linked) {
    std::array<char, 8192> log{};
    glGetProgramInfoLog(program, static_cast<GLsizei>(log.size()), nullptr, log.data());
    glDeleteProgram(program);
    throw std::runtime_error(eye + " program link failed: " + log.data());
  }
  GLint const attribute = glGetAttribLocation(program, "in_POSITION0");
  Require(attribute >= 0, "translated POSITION attribute missing");
  GLuint vao = 0, buffer = 0;
  glGenVertexArrays(1, &vao);
  glBindVertexArray(vao);
  glGenBuffers(1, &buffer);
  glBindBuffer(GL_ARRAY_BUFFER, buffer);
  // A full-screen triangle. The geometry stage must emit it; drawing only
  // VS/FS, losing EmitVertex or routing the right eye to gl_Layer=1 fails.
  GLfloat const vertices[] = {-1, -1, 0, 1, 3, -1, 0, 1, -1, 3, 0, 1};
  glBufferData(GL_ARRAY_BUFFER, sizeof(vertices), vertices, GL_STATIC_DRAW);
  glEnableVertexAttribArray(static_cast<GLuint>(attribute));
  glVertexAttribPointer(static_cast<GLuint>(attribute), 4, GL_FLOAT, GL_FALSE, 0, nullptr);
  glViewport(0, 0, 32, 32);
  glDisable(GL_DITHER);
  glClearColor(0, 0, 1, 1);
  glClear(GL_COLOR_BUFFER_BIT);
  glUseProgram(program);
  std::array<GLuint, 2> textures{};
  if (depth) {
    glGenTextures(2, textures.data());
    for (int unit = 0; unit < 2; ++unit) {
      glActiveTexture(GL_TEXTURE0 + unit);
      glBindTexture(GL_TEXTURE_2D, textures[unit]);
      glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_NEAREST);
      glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_NEAREST);
      if (unit == 0) {
        unsigned int value = expected == 0 ? 0x40000000u : 0xc0000000u;
        glTexImage2D(GL_TEXTURE_2D, 0, GL_DEPTH_COMPONENT24, 1, 1, 0, GL_DEPTH_COMPONENT, GL_UNSIGNED_INT, &value);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_COMPARE_MODE, GL_NONE);
      } else {
        std::array<unsigned char, 4> value{static_cast<unsigned char>(expected == 0 ? 32 : 223), 0, 0, 255};
        glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA8, 1, 1, 0, GL_RGBA, GL_UNSIGNED_BYTE, value.data());
      }
      GLint location = glGetUniformLocation(program, unit == 0 ? "_CameraDepthTexture" : "_MainTex");
      Require(location >= 0, "translated camera texture sampler missing");
      glUniform1i(location, unit);
    }
  }
  glDrawArrays(GL_TRIANGLES, 0, 3);
  std::array<unsigned char, 4> pixel{};
  glReadPixels(16, 16, 1, 1, GL_RGBA, GL_UNSIGNED_BYTE, pixel.data());
  GLenum const error = glGetError();
  glDeleteBuffers(1, &buffer);
  glDeleteVertexArrays(1, &vao);
  glDeleteProgram(program);
  glDeleteTextures(2, textures.data());
  Require(error == GL_NO_ERROR, eye + " render produced GL error " + std::to_string(error));
  std::array<int, 3> wanted = depth ? std::array<int, 3>{expected == 0 ? 64 : 191, expected == 0 ? 32 : 223, expected}
                                    : std::array<int, 3>{expected, expected, expected};
  for (int channel = 0; channel < 3; ++channel)
    Require(pixel[channel] >= wanted[channel] - 3 && pixel[channel] <= wanted[channel] + 3,
            eye + " center pixel incorrect: " + std::to_string(pixel[0]) + "," +
            std::to_string(pixel[1]) + "," + std::to_string(pixel[2]));
  std::printf("PASS %s %s: rgba=%u,%u,%u,%u\n", eye.c_str(), depth ? "depth/blit" : "geometry", pixel[0], pixel[1], pixel[2], pixel[3]);
}

static void DrawNativePerspective(std::string const& directory) {
  using Attach = void (*)(GLenum, GLenum, GLuint, GLint, GLint, GLsizei);
  auto attach = reinterpret_cast<Attach>(eglGetProcAddress("glFramebufferTextureMultiviewOVR"));
  Require(attach != nullptr, "multiview framebuffer entry point unavailable");
  GLuint program = glCreateProgram();
  for (auto const& [type, suffix] : std::array<std::pair<GLenum, char const*>, 2>{
         {{GL_VERTEX_SHADER, ".vert"}, {GL_FRAGMENT_SHADER, ".frag"}}}) {
    auto shader = Compile(type, directory + "/native-perspective" + suffix);
    glAttachShader(program, shader); glDeleteShader(shader);
  }
  glLinkProgram(program);
  GLint linked = 0; glGetProgramiv(program, GL_LINK_STATUS, &linked);
  Require(linked != 0, "native perspective program did not link");
  GLuint texture = 0, draw = 0, read = 0, vao = 0;
  glGenTextures(1, &texture); glBindTexture(GL_TEXTURE_2D_ARRAY, texture);
  glTexStorage3D(GL_TEXTURE_2D_ARRAY, 1, GL_RGBA8, 32, 32, 2);
  glGenFramebuffers(1, &draw); glBindFramebuffer(GL_FRAMEBUFFER, draw);
  attach(GL_FRAMEBUFFER, GL_COLOR_ATTACHMENT0, texture, 0, 0, 2);
  Require(glCheckFramebufferStatus(GL_FRAMEBUFFER) == GL_FRAMEBUFFER_COMPLETE, "native multiview framebuffer incomplete");
  glViewport(0, 0, 32, 32); glClearColor(0, 0, 1, 1); glClear(GL_COLOR_BUFFER_BIT);
  glGenVertexArrays(1, &vao); glBindVertexArray(vao); glUseProgram(program);
  glDrawArrays(GL_TRIANGLES, 0, 3);
  Require(glGetError() == GL_NO_ERROR, "native perspective draw produced a GL error");
  glGenFramebuffers(1, &read);
  for (int eye = 0; eye != 2; ++eye) {
    // ReadPixels cannot read a multiview FBO. Attach one layer to a separate
    // read framebuffer without changing the multiview draw attachment.
    glBindFramebuffer(GL_READ_FRAMEBUFFER, read);
    glFramebufferTextureLayer(GL_READ_FRAMEBUFFER, GL_COLOR_ATTACHMENT0, texture, 0, eye);
    Require(glCheckFramebufferStatus(GL_READ_FRAMEBUFFER) == GL_FRAMEBUFFER_COMPLETE, "native read framebuffer incomplete");
    std::array<unsigned char, 4> pixel{};
    glReadPixels(16, 16, 1, 1, GL_RGBA, GL_UNSIGNED_BYTE, pixel.data());
    Require(glGetError() == GL_NO_ERROR && pixel[0] < 3 && pixel[1] < 3 && pixel[2] > 252,
            "perspective-empty program unexpectedly changed a multiview layer");
    std::printf("PASS native perspective view %d: rgba=%u,%u,%u,%u\n", eye, pixel[0], pixel[1], pixel[2], pixel[3]);
  }
  glBindFramebuffer(GL_FRAMEBUFFER, 0); glBindVertexArray(0); glUseProgram(0);
  glDeleteVertexArrays(1, &vao); glDeleteProgram(program);
  glDeleteFramebuffers(1, &draw); glDeleteFramebuffers(1, &read); glDeleteTextures(1, &texture);
}

// Compile/link caller-supplied map pipelines on the actual GLES driver without
// opening Unity or drawing the map. One filename stem per line; .vert/.frag
// are required, .geom is optional, and .tesc/.tese must be supplied together.
// Keep these user-owned sources separate
// from the distributable synthetic smoke-test fixtures.
static int LinkPrograms(std::string const& manifest) {
  std::ifstream list(manifest);
  Require(list.good(), "cannot read pipeline manifest");
  auto slash = manifest.find_last_of('/');
  std::string const directory = slash == std::string::npos ? "" : manifest.substr(0, slash + 1);
  std::string stem;
  int passed = 0, failed = 0;
  while (std::getline(list, stem)) {
    if (stem.empty()) continue;
    GLuint program = glCreateProgram();
    try {
      Require(stem.find('/') == std::string::npos && stem.find("..") == std::string::npos, "invalid pipeline stem");
      bool const control = std::ifstream(directory + stem + ".tesc").good();
      bool const evaluation = std::ifstream(directory + stem + ".tese").good();
      Require(control == evaluation, "tessellation control and evaluation stages must be paired");
      for (auto const& [stage, suffix] : std::array<std::pair<GLenum, char const*>, 5>{
             {{GL_VERTEX_SHADER, ".vert"}, {GL_TESS_CONTROL_SHADER, ".tesc"}, {GL_TESS_EVALUATION_SHADER, ".tese"},
              {GL_GEOMETRY_SHADER, ".geom"}, {GL_FRAGMENT_SHADER, ".frag"}}}) {
        auto const path = directory + stem + suffix;
        if (stage == GL_GEOMETRY_SHADER && !std::ifstream(path).good()) continue;
        if ((stage == GL_TESS_CONTROL_SHADER || stage == GL_TESS_EVALUATION_SHADER) && !control) continue;
        auto shader = Compile(stage, path);
        glAttachShader(program, shader); glDeleteShader(shader);
      }
      glLinkProgram(program);
      GLint ok = 0; glGetProgramiv(program, GL_LINK_STATUS, &ok);
      if (!ok) {
        std::array<char, 8192> log{};
        glGetProgramInfoLog(program, static_cast<GLsizei>(log.size()), nullptr, log.data());
        throw std::runtime_error(std::string("link: ") + log.data());
      }
      Require(glGetError() == GL_NO_ERROR, "GL error during pipeline validation");
      ++passed; std::printf("PASS pipeline %s\n", stem.c_str());
    } catch (std::exception const& e) {
      ++failed; std::printf("FAIL pipeline %s: %s\n", stem.c_str(), e.what());
      while (glGetError() != GL_NO_ERROR) {}
    }
    glDeleteProgram(program);
    std::fflush(stdout);
  }
  std::printf("Pipeline checks: %d passed, %d failed (driver link only; not Unity pixels/performance)\n", passed, failed);
  return failed == 0 && passed > 0 ? 0 : 1;
}

int main(int argc, char** argv) {
  bool const linkOnly = argc == 3 && std::string(argv[1]) == "--link-list";
  if (argc != 2 && !linkOnly) { std::fprintf(stderr, "usage: geometry-probe <generated-shader-directory> | --link-list <manifest>\n"); return 2; }
  try {
    Context context;
    context.Init();
    std::printf("GPU: %s\nGL: %s\n", glGetString(GL_RENDERER), glGetString(GL_VERSION));
    GLint major = 0, minor = 0, count = 0;
    glGetIntegerv(GL_MAJOR_VERSION, &major);
    glGetIntegerv(GL_MINOR_VERSION, &minor);
    glGetIntegerv(GL_NUM_EXTENSIONS, &count);
    bool combined = false;
    for (int i = 0; i < count; ++i) {
      std::string const ext(reinterpret_cast<char const*>(glGetStringi(GL_EXTENSIONS, i)));
      if (ext == "GL_EXT_multiview_tessellation_geometry_shader") combined = true;
    }
    std::printf("combined multiview/geometry/tessellation extension: %s\n", combined ? "yes" : "no");
    Require(major > 3 || (major == 3 && minor >= 2), "this probe requires GLES 3.2 geometry shaders");
    if (linkOnly) return LinkPrograms(argv[2]);
    DrawEye(argv[1], "left", 0);
    DrawEye(argv[1], "right", 255);
    DrawEye(argv[1], "left", 0, true);
    DrawEye(argv[1], "right", 255, true);
    DrawNativePerspective(argv[1]);
    std::puts("PASS separate-eye geometry and depth/blit smoke test (not a Unity integration or performance test)");
    return 0;
  } catch (std::exception const& e) {
    std::fprintf(stderr, "FAIL: %s (EGL error 0x%x)\n", e.what(), eglGetError());
    return 1;
  }
}
